// ============================================================
// CODE A — "Relever Telegram" (workflow: Atelier Figurines 3D - Bot ami)
// Récupère les nouveaux messages du bot et les passe au nœud suivant.
// ⚠️ À REMPLIR une seule fois : le token BotFather ci-dessous.
// ============================================================
const CONFIG = {
  TELEGRAM_TOKEN: 'A_REMPLIR_token_botfather',
  SUPABASE_URL: 'https://bmvytqfddrfgcgokoxfn.supabase.co',
  SUPABASE_SERVICE_KEY: 'A_REMPLIR_service_role_key',
  MESHY_KEY: 'A_REMPLIR_cle_api_meshy',          // laisser tel quel tant que le compte Meshy n'existe pas
  FRANCK_CHAT_ID: 'A_REMPLIR_chat_id_franck',     // pour les notifications à Franck
  APP_URL: 'https://bigandfranck89-prog.github.io/atelier-figurines-3d',
};

if (CONFIG.TELEGRAM_TOKEN.startsWith('A_REMPLIR')) return [];

const sd = $getWorkflowStaticData('global');
const offset = sd.tgOffset || 0;

const res = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://api.telegram.org/bot${CONFIG.TELEGRAM_TOKEN}/getUpdates`,
  qs: { offset, timeout: 0, allowed_updates: JSON.stringify(['message', 'callback_query']) },
  json: true,
});

const updates = (res && res.result) || [];
if (updates.length === 0) return [];

// Marque immédiatement les updates comme consommés (évite les doublons si deux
// exécutions se chevauchent pendant une génération d'image un peu longue).
const maxId = Math.max(...updates.map(u => u.update_id));
sd.tgOffset = maxId + 1;
await this.helpers.httpRequest({
  method: 'GET',
  url: `https://api.telegram.org/bot${CONFIG.TELEGRAM_TOKEN}/getUpdates`,
  qs: { offset: maxId + 1, limit: 1, timeout: 0 },
  json: true,
});

return updates.map(u => ({ json: { update: u, config: CONFIG } }));

// ============================================================
// CODE B — "Machine à figurines" (workflow: Atelier Figurines 3D - Bot ami)
// Toute la logique : création, boucle de critique image, lancement 3D,
// boucle de validation 3D, alerte licence, notifications Franck.
// Rien à remplir ici : la config vient du nœud "Relever Telegram".
// ============================================================
const out = [];

// ---------- petits helpers ----------
const mkTg = (C) => async (method, body) =>
  this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${C.TELEGRAM_TOKEN}/${method}`,
    body, json: true,
  }).catch(e => ({ error: String(e && e.message || e) }));

const mkSb = (C) => async (method, path, body) =>
  this.helpers.httpRequest({
    method,
    url: `${C.SUPABASE_URL}/rest/v1/${path}`,
    headers: {
      apikey: C.SUPABASE_SERVICE_KEY,
      Authorization: `Bearer ${C.SUPABASE_SERVICE_KEY}`,
      Prefer: 'return=representation',
      'Content-Type': 'application/json',
    },
    body, json: true,
  });

const LICENCE_MOTS = ['marvel','pokemon','pokémon','pikachu','disney','star wars','starwars','mario','luigi','zelda','link ','batman','superman','spiderman','spider-man','naruto','dragon ball','goku','vegeta','harry potter','avengers','hulk','iron man','thor ','sonic','kirby','minecraft','fortnite','one piece','luffy','stitch','groot','yoda','dark vador','darth vader','deadpool','wolverine','ninjago','transformers','gundam','demon slayer','tanjiro'];

const detecteLicence = (t) => {
  const s = ' ' + t.toLowerCase() + ' ';
  return LICENCE_MOTS.some(m => s.includes(m));
};

const promptFigurine = (description) =>
  `${description}, figurine de collection, corps entier, un seul personnage, sur un petit socle rond simple, ` +
  `fond de studio uni et clair, très détaillé, style adapté à l'impression 3D, collectible figurine, full body, plain background`;

const urlImage = (prompt, seed) =>
  `https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}?width=1024&height=1024&model=flux&nologo=true&seed=${seed}`;

// Force la génération côté Pollinations (met l'image en cache) avant que Telegram n'aille la chercher.
const chauffeImage = async (url) => {
  try { await this.helpers.httpRequest({ method: 'GET', url, encoding: 'arraybuffer', timeout: 120000 }); }
  catch (e) { /* tant pis, Telegram réessaiera */ }
};

const AVERT_LICENCE = '\n\n⚠️ Personnage sous licence : impression PERSO uniquement — interdit à la vente.';

const clavierImage = (id) => ({ inline_keyboard: [[
  { text: '✅ Je valide cette image', callback_data: `v_img:${id}` },
  { text: '🔄 Refaire', callback_data: `r_img:${id}` },
]]});

const clavier3D = (id) => ({ inline_keyboard: [
  [{ text: '✅ Je valide la 3D', callback_data: `v_3d:${id}` }],
  [{ text: '🔁 Relancer la sculpture 3D', callback_data: `r_3d:${id}` },
   { text: '↩️ Modifier l\'image', callback_data: `b_img:${id}` }],
]});

const lanceMeshy = async (C, fig, tg, sb) => {
  if (!C.MESHY_KEY || C.MESHY_KEY.startsWith('A_REMPLIR')) {
    await tg('sendMessage', { chat_id: fig.telegram_chat_id,
      text: '✅ Image validée et enregistrée !\n\n(La sculpture 3D automatique n\'est pas encore branchée — Franck s\'en occupe et tu recevras ta 3D ici dès que c\'est prêt.)' });
    if (!String(C.FRANCK_CHAT_ID).startsWith('A_REMPLIR')) {
      await tg('sendMessage', { chat_id: C.FRANCK_CHAT_ID,
        text: `🔔 Figurine #${fig.id} : image validée par l'ami, Meshy pas encore branché.\nImage : ${fig.image_url}` });
    }
    return;
  }
  const task = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.meshy.ai/openapi/v1/image-to-3d',
    headers: { Authorization: `Bearer ${C.MESHY_KEY}` },
    body: { image_url: fig.image_url, should_remesh: true, should_texture: true, enable_pbr: false },
    json: true,
  });
  const taskId = task && (task.result || task.id);
  await sb('PATCH', `atelier_figurines?id=eq.${fig.id}`,
    { meshy_task_id: String(taskId), statut: '3d_en_cours', maj_le: new Date().toISOString() });
  await tg('sendMessage', { chat_id: fig.telegram_chat_id,
    text: '🔧 Je sculpte ta figurine en 3D… Ça prend en général 2 à 5 minutes, je t\'envoie le résultat ici dès que c\'est prêt !' });
};

// ---------- boucle principale ----------
for (const item of $input.all()) {
  const u = item.json.update;
  const C = item.json.config;
  const tg = mkTg(C);
  const sb = mkSb(C);

  try {
    // ============ BOUTONS ============
    if (u.callback_query) {
      const cq = u.callback_query;
      const chat = cq.message.chat.id;
      const [action, idStr] = String(cq.data || '').split(':');
      const id = parseInt(idStr, 10);
      await tg('answerCallbackQuery', { callback_query_id: cq.id });

      const figs = await sb('GET', `atelier_figurines?id=eq.${id}&limit=1`);
      const fig = figs && figs[0];
      if (!fig) { await tg('sendMessage', { chat_id: chat, text: 'Hmm, je ne retrouve plus cette figurine. Décris-m\'en une nouvelle !' }); continue; }

      if (action === 'v_img') {
        const iters = await sb('GET', `atelier_iterations?figurine_id=eq.${id}&etape=eq.image&order=version.desc&limit=1`);
        const derniere = iters && iters[0];
        const imageUrl = (derniere && derniere.resultat_url) || fig.image_url;
        await sb('PATCH', `atelier_iterations?id=eq.${derniere.id}`, { valide: true });
        const upd = await sb('PATCH', `atelier_figurines?id=eq.${id}`,
          { statut: 'image_validee', image_url: imageUrl, maj_le: new Date().toISOString() });
        await lanceMeshy(C, upd[0], tg, sb);
      }
      else if (action === 'r_img') {
        await tg('sendMessage', { chat_id: chat,
          text: '🔄 Pas de souci ! Dis-moi ce qui ne va pas (couleurs, pose, style, détails…) et je refais une proposition.' });
      }
      else if (action === 'v_3d') {
        await sb('PATCH', `atelier_figurines?id=eq.${id}`, { statut: '3d_valide', maj_le: new Date().toISOString() });
        await tg('sendMessage', { chat_id: chat,
          text: '🎉 Excellent ! Ta figurine 3D est validée. Franck prépare maintenant le fichier d\'impression (.3mf) avec les bons réglages pour ta P2S — tu le reçois bientôt !' });
        if (!String(C.FRANCK_CHAT_ID).startsWith('A_REMPLIR')) {
          await tg('sendMessage', { chat_id: C.FRANCK_CHAT_ID,
            text: `✅ Figurine #${id} — 3D VALIDÉE par l'ami !\n« ${fig.demande} »\nModèle : ${fig.model_url}\n→ À préparer en .3mf (Bambu Studio, profil P2S).${fig.licence ? AVERT_LICENCE : ''}` });
        }
      }
      else if (action === 'r_3d') {
        await sb('PATCH', `atelier_figurines?id=eq.${id}`, { model_url: null, maj_le: new Date().toISOString() });
        const figR = { ...fig, model_url: null };
        await lanceMeshy(C, figR, tg, sb);
      }
      else if (action === 'b_img') {
        await sb('PATCH', `atelier_figurines?id=eq.${id}`, { statut: 'image_en_cours', maj_le: new Date().toISOString() });
        await tg('sendMessage', { chat_id: chat, text: '↩️ Ok, on retravaille l\'image de départ. Dis-moi ce que tu veux changer !' });
      }
      out.push({ json: { ok: true, action, figurine: id } });
      continue;
    }

    // ============ MESSAGES TEXTE ============
    if (!u.message || !u.message.text) continue;
    const chat = u.message.chat.id;
    const texte = u.message.text.trim();

    if (texte === '/start' || texte === '/aide') {
      await tg('sendMessage', { chat_id: chat, text:
        '👋 Salut ! Je suis l\'Atelier Figurines 3D.\n\n' +
        '1️⃣ Décris-moi la figurine de tes rêves (ex : « un dragon qui dort sur un tas d\'or »)\n' +
        '2️⃣ Je te propose une image — tu critiques, je corrige, jusqu\'à ce que ce soit EXACTEMENT ce que tu veux\n' +
        '3️⃣ Je la sculpte en 3D — pareil, tu valides quand c\'est parfait\n' +
        '4️⃣ Franck te prépare le fichier d\'impression pour ta P2S 🖨️\n\nVas-y, décris-moi ta première figurine !' });
      continue;
    }

    const enCours = await sb('GET',
      `atelier_figurines?telegram_chat_id=eq.${chat}&statut=in.(image_en_cours,3d_en_cours)&order=id.desc&limit=1`);
    const fig = enCours && enCours[0];

    if (!fig) {
      // ---- Nouvelle figurine ----
      const licence = detecteLicence(texte);
      const prompt = promptFigurine(texte);
      const seed = (Date.now() % 900000) + 1;
      const img = urlImage(prompt, seed);
      const inserted = await sb('POST', 'atelier_figurines', {
        demande: texte, usage: 'perso', licence, statut: 'image_en_cours',
        prompt_image: prompt, telegram_chat_id: String(chat),
      });
      const nid = inserted[0].id;
      await sb('POST', 'atelier_iterations', { figurine_id: nid, etape: 'image', version: 1, prompt, resultat_url: img });
      await tg('sendMessage', { chat_id: chat, text: '🎨 Super idée ! Je dessine ta figurine, quelques secondes…' });
      await chauffeImage(img);
      await tg('sendPhoto', { chat_id: chat, photo: img,
        caption: `Voilà ma première proposition pour : « ${texte} »\n\nDis-moi ce que tu en penses — ou valide si c'est déjà ça !${licence ? AVERT_LICENCE : ''}`,
        reply_markup: clavierImage(nid) });
    }
    else if (fig.statut === 'image_en_cours') {
      // ---- Critique de l'image → nouvelle version ----
      const iters = await sb('GET', `atelier_iterations?figurine_id=eq.${fig.id}&etape=eq.image&order=version.desc&limit=1`);
      const prev = iters && iters[0];
      const version = (prev ? prev.version : 0) + 1;
      if (prev) await sb('PATCH', `atelier_iterations?id=eq.${prev.id}`, { retour_ami: texte });
      const prompt = `${fig.prompt_image}. Correction demandée : ${texte}`;
      const seed = (Date.now() % 900000) + 1;
      const img = urlImage(prompt, seed);
      await sb('PATCH', `atelier_figurines?id=eq.${fig.id}`, { prompt_image: prompt, maj_le: new Date().toISOString() });
      await sb('POST', 'atelier_iterations', { figurine_id: fig.id, etape: 'image', version, prompt, resultat_url: img });
      await tg('sendMessage', { chat_id: chat, text: `🖌️ C'est noté ! Je corrige (version ${version})…` });
      await chauffeImage(img);
      await tg('sendPhoto', { chat_id: chat, photo: img,
        caption: `Version ${version} — j'ai tenu compte de : « ${texte} »${fig.licence ? AVERT_LICENCE : ''}`,
        reply_markup: clavierImage(fig.id) });
    }
    else if (fig.statut === '3d_en_cours') {
      // ---- Remarque pendant/après la 3D ----
      await sb('POST', 'atelier_iterations', { figurine_id: fig.id, etape: '3d', version: 1, retour_ami: texte });
      await tg('sendMessage', { chat_id: chat,
        text: 'Bien noté ! Pour la 3D, le mieux est de choisir :\n• relancer une nouvelle sculpture,\n• ou revenir à l\'image pour la modifier (c\'est là qu\'on contrôle le mieux le résultat).',
        reply_markup: clavier3D(fig.id) });
    }
    out.push({ json: { ok: true, chat, texte } });
  } catch (e) {
    out.push({ json: { ok: false, erreur: String(e && e.message || e), update_id: u.update_id } });
  }
}

return out.length ? out : [{ json: { ok: true, rien: true } }];
